import type { Coordinate, OpenMarchShowData } from "@openmarch/schema";
import type { CompiledDrill, CompiledDrillMovement } from "./compiled-drill";

function coordinateKey(marcherId: number, pageId: string): string {
  return `${marcherId}:${pageId}`;
}

function viewerCoordinate(
  coordinate: Coordinate,
  yOrigin: "front" | "center",
  stepScale: number,
): { x: number; y: number; facing: number } {
  return {
    x: 80 - coordinate.xSteps * stepScale,
    y: (yOrigin === "front" ? coordinate.ySteps : 42 + coordinate.ySteps) * stepScale + 42 * (1 - stepScale),
    facing: (270 + (coordinate.rotation_degrees ?? 0)) % 360,
  };
}

export function compileOpenMarchShow(show: OpenMarchShowData): CompiledDrill {
  if (show.performers.length === 0) throw new Error("OpenMarch show has no performers");
  if (show.pages.length === 0) throw new Error("OpenMarch show has no pages");

  const performers = [...show.performers].sort((left, right) => left.id - right.id);
  const labels = performers.map(performer => performer.label);
  if (new Set(labels).size !== labels.length) throw new Error("OpenMarch performer labels must be unique");

  const pages = [...show.pages].sort((left, right) => left.startBeatIndex - right.startBeatIndex);
  for (let index = 1; index < pages.length; index += 1) {
    if (pages[index].startBeatIndex <= pages[index - 1].startBeatIndex) {
      throw new Error("OpenMarch page beat indices must be unique and increasing");
    }
  }

  const coordinates = new Map<string, Coordinate>();
  for (const coordinate of show.coordinates) {
    const key = `${coordinate.marcherId}:${coordinate.pageId}`;
    if (coordinates.has(key)) throw new Error(`OpenMarch has duplicate coordinates for ${key}`);
    coordinates.set(key, coordinate);
  }

  const stepScale = show.metadata.performanceArea.inchesPerStep / 22.5;
  if (!Number.isFinite(stepScale) || stepScale <= 0) throw new Error("OpenMarch inchesPerStep must be positive");
  const yOrigin = show.metadata.performanceArea.yOrigin;
  const totalBeats = show.tempoSections.reduce((sum, section) => sum + section.numberOfBeats, 0);

  const sets = pages.map((page, pageIndex) => {
    const nextPage = pages[pageIndex + 1];
    const beats = Math.max(0, (nextPage?.startBeatIndex ?? totalBeats) - page.startBeatIndex);
    const movements: Record<string, CompiledDrillMovement[]> = Object.fromEntries(performers.map((performer, performerIndex) => {
      const current = coordinates.get(coordinateKey(performer.id, page.id));
      if (!current) throw new Error(`OpenMarch page ${page.name} has no coordinate for ${performer.label}`);
      const start = viewerCoordinate(current, yOrigin, stepScale);
      const next = nextPage ? coordinates.get(coordinateKey(performer.id, nextPage.id)) : undefined;
      if (nextPage && !next) throw new Error(`OpenMarch page ${nextPage.name} has no coordinate for ${performer.label}`);
      if (!next) {
        return [labels[performerIndex], [{ type: "stand", beats, x: start.x, y: start.y, facing: start.facing }]];
      }
      const end = viewerCoordinate(next, yOrigin, stepScale);
      if (start.x === end.x && start.y === end.y) {
        return [labels[performerIndex], [{ type: "stand", beats, x: start.x, y: start.y, facing: start.facing }]];
      }
      return [labels[performerIndex], [{
        type: "even",
        beats,
        x1: start.x,
        y1: start.y,
        x2: end.x,
        y2: end.y,
        facing: start.facing,
      }]];
    }));
    return { label: page.name, beats, movements };
  });

  const title = show.metadata.info?.title || "OpenMarch drill";
  return {
    format: "openmarch",
    version: show.omSchemaVersion,
    title,
    labels,
    setNoun: "Page",
    sets,
  };
}
