import type { CompiledDrill, CompiledDrillMovement } from "./compiled-drill";

interface CalChartViewerFile {
  meta: { type: "viewer"; version?: string; index_name?: string };
  show: {
    title?: string;
    labels: string[];
    sheets: Array<{
      label: string;
      beats: number;
      movements: Record<string, CompiledDrillMovement[]>;
    }>;
  };
}

export function isCalChartViewerFile(data: unknown): data is CalChartViewerFile {
  return Boolean(data && typeof data === "object" && (data as Partial<CalChartViewerFile>).meta?.type === "viewer");
}

export function compileCalChartViewer(data: unknown): CompiledDrill {
  if (!isCalChartViewerFile(data) || !data.show || !Array.isArray(data.show.labels) || !Array.isArray(data.show.sheets)) {
    throw new Error("This is not a compiled CalChart .viewer file; export the .shw show with CalChart's Online Viewer export");
  }
  const title = data.show.title && !data.show.title.startsWith("(MANUAL)")
    ? data.show.title
    : data.meta.index_name && !data.meta.index_name.startsWith("(MANUAL)")
      ? data.meta.index_name
      : "CalChart drill";
  return {
    format: "calchart-viewer",
    version: data.meta.version,
    title,
    labels: data.show.labels,
    setNoun: "Sheet",
    sets: data.show.sheets,
  };
}
